import pandas as pd,numpy as np
from scipy.spatial.distance import cdist
R=pd.read_csv('dataset/readings.csv');R.timestamp=pd.to_datetime(R.timestamp);S=pd.read_csv('dataset/stations.csv').set_index('station_id')
rows=[]
for pol,g in R.groupby('pollutant'):
 X=g.pivot(index='timestamp',columns='station_id',values='current_reading').sort_index().interpolate(limit_direction='both');loc=S.loc[X.columns]
 D=cdist(np.c_[loc.latitude*111,loc.longitude*70],np.c_[loc.latitude*111,loc.longitude*70]);np.fill_diagonal(D,np.inf)
 for j,st in enumerate(X):
  for scope,peers in [('nn10',list(X.columns[np.argsort(D[j])[:10]])),('district',[x for x in X if x!=st and loc.loc[x,'district']==loc.loc[st,'district']]),('all',[x for x in X if x!=st])]:
   y=X[st]
   vals={}
   for lag in range(-4,5): vals[lag]=np.median([y.corr(X[p].shift(lag)) for p in peers])
   best=max([z for z in vals if z!=0],key=lambda z:vals[z]);gain=vals[best]-vals[0]
   # fraction peers individually improve at selected lag
   c0=np.array([y.corr(X[p]) for p in peers]);cl=np.array([y.corr(X[p].shift(best)) for p in peers])
   rows.append([st,scope,vals[0],best,vals[best],gain,np.mean(cl>c0),np.median(cl-c0)])
O=pd.DataFrame(rows,columns=['st','scope','c0','lag','best','gain','frac','medindgain'])
C=O.groupby('st').agg(medgain=('gain','median'),mingain=('gain','min'),maxgain=('gain','max'),medfrac=('frac','median'),medindgain=('medindgain','median'),lag=('lag',lambda x:x.mode().iloc[0])).sort_values('medgain',ascending=False)
print(C.head(30).to_string())
for st in C.head(15).index:
 print('\n',st);print(O[O.st==st].to_string(index=False))
